fa_text = fa.read_text()
fa_block = '''\n\n## 十一、第八功德：如法奉行、戒忍布施、慈悲方便化人\n\n《十功德品第三》第八功德说，持经者“受持、读诵、书写、顶戴，如法奉行，坚固戒忍，兼行檀度，深发慈悲，以此无上大乘《无量义经》广为人说”。（WLYJ-P03-011）这里把敬经、奉行、六度中的戒忍布施、慈悲与说法直接连成一条行法链条。\n\n面对“先来都不信有罪福者”，经文说“以是经示之，设种种方便，强化令信”，并进一步说“发其人心，欻然得回；信心既发，勇猛精进故，能得是经威德势力，得道、得果”。因此方便化人的方向，是依经、慈悲、随众生实际而说，使其心真实回转并进入精进修行。\n\n本段应与前文“随宜广说”“所可演说无违无失”“依佛……教法而敷演之”合读：可以施设方便，但不能为了令信而违失经义。\n'''
if '## 十一、第八功德：如法奉行、戒忍布施、慈悲方便化人' not in fa_text:
    fa.write_text(fa_text.rstrip() + fa_block + '\n')

idx = index.read_text()
